const { EmbedBuilder, ActionRowBuilder, ButtonBuilder, ButtonStyle, ChannelType, ComponentType } = require('discord.js');
const PaymentProcessor = require('../structures/PaymentProcessor');

const crypto = require('crypto')
const { Cart, Payment } = require('../database/models/Models');

class CartClass {
    /**
     * Cria uma instância de CartClass
     * @param {Discord.Client} client 
     * @param {Discord.Interaction} interaction 
     * @param {String} productId 
     * @param {Object} productData 
     */
    constructor(client, interaction, productId, productData, user) {
        this.client = client;
        this.interaction = interaction;
        this.productId = productId;
        this.productData = productData;
        this.user = interaction?.user || this.client.users.cache.get(user);
        this.paymentProcessor = new PaymentProcessor();
        this.inactivityTimer = null;
        this.cartId = crypto.randomBytes(10).toString('hex');
        this.channel = null;
        this.quantity = 1;
        this.selectedPlan = null;
        this.inactivityDelay = 1000 * 60 * 5
        this.message = false
    }

    /**
     * Envia um log para o canal de logs configurado
     * @param {EmbedBuilder} embed 
     */
    sendLog = async (embed) => {
        const logChannelId = '1264758034979360860'; // Substitua pelo ID real do canal de logs
        if (logChannelId) {
            const logChannel = this.client.channels.cache.get(logChannelId);
            if (logChannel) {
                await logChannel.send({ embeds: [embed] });
            }
        }
    };

    createInactivityEmbed = () => {
        return new EmbedBuilder()
            .setColor('#FF0000')
            .setDescription(`### 🙁 Seu carrinho foi encerrado\nOlá ${this.user},\n\nSeu carrinho foi cancelado devido à inatividade, mas, você pode retomar sua compra a qualquer momento. Esperamos vê-lo novamente em breve. \n\n-# Atenciosamente, Nyox Applications.`)
    };

    /**
     * Cria uma resposta para carrinho já existente
     * @param {Discord.GuildChannel} channel 
     * @returns {Object}
     */
    createCartOpenEmbed = (channel) => {
        return {
            content: `Você já tem um carrinho criado!`,
            ephemeral: true,
            components: [
                new ActionRowBuilder().addComponents(
                    new ButtonBuilder()
                        .setStyle(ButtonStyle.Link)
                        .setLabel("Carrinho")
                        .setURL(channel.url)
                )
            ]
        };
    };

    /**
     * Cria uma embed de sucesso ao abrir o carrinho
     * @param {String} channelURL 
     * @returns {Object}
     */
    createCartSuccessEmbed = (channelURL) => {
        return {
            content: "",
            embeds: [
                new EmbedBuilder()
                    .setColor('#060A18')
                    .setDescription(`### Olá, ${this.user}, seu carrinho foi aberto!\n\`🌟\` Você está prestes a adquirir o ${this.productData.productName}, um sistema exclusivo da **Nyox Applications** com a melhor qualidade do mercado.\n-# Para ser redirecionado ao carrinho, clique no botão abaixo.`)
            ],
            components: [
                new ActionRowBuilder().addComponents(
                    new ButtonBuilder()
                        .setLabel("Acessar carrinho")
                        .setStyle(ButtonStyle.Link)
                        .setEmoji("🛒")
                        .setURL(channelURL)
                )
            ]
        };
    };

    /**
     * Cria uma embed para seleção de plano
     * @returns {Object}
     */
    createPlanSelectionEmbed = () => {
        const { preco } = this.productData;
        const planFields = [];

        if (preco.mensal.onoff) {
            planFields.push({
                name: "📅 Plano Mensal",
                value: `**30 dias** - R$${preco.mensal.preco}`,
                inline: true
            });
        }

        if (preco.quizena.onoff) {
            planFields.push({
                name: "🗓️ Plano Quinzenal",
                value: `**15 dias** - R$${preco.quizena.preco}`,
                inline: true
            });
        }

        if (preco.semanal.onoff) {
            planFields.push({
                name: "📆 Plano Semanal",
                value: `**7 dias** - R$${preco.semanal.preco}`,
                inline: true
            });
        }

        return {
            content: `${this.user} <@&995792293309190184>`,
            embeds: [
                new EmbedBuilder()
                    .setTitle("🛒 Sistema de Compras")
                    .setColor("#00BFFF") // Azul Claro - Ajuste a cor conforme sua preferência
                    .setAuthor({
                        name: this.client.user.username,
                        iconURL: this.client.user.displayAvatarURL({ dynamic: true })
                    })
                    .setDescription(`👋 Olá, ${this.user.username}! Falta pouco para finalizar sua compra. Escolha um dos planos abaixo para continuar:`)
                    .addFields(planFields)
            ],
            components: [this.createPlanButtons()]
        };
    };

    /**
     * Cria os botões de seleção de plano
     * @returns {ActionRowBuilder}
     */
    createPlanButtons = () => {
        const row = new ActionRowBuilder();

        if (this.productData.preco.mensal.onoff) {
            row.addComponents(
                new ButtonBuilder()
                    .setEmoji("📅")
                    .setLabel("30 Dias")
                    .setStyle(ButtonStyle.Primary)
                    .setCustomId("30DiasCart")
            );
        }

        if (this.productData.preco.quizena.onoff) {
            row.addComponents(
                new ButtonBuilder()
                    .setEmoji("📅")
                    .setLabel("15 Dias")
                    .setStyle(ButtonStyle.Primary)
                    .setCustomId("15DiasCart")
            );
        }

        if (this.productData.preco.semanal.onoff) {
            row.addComponents(
                new ButtonBuilder()
                    .setEmoji("📅")
                    .setLabel("7 Dias")
                    .setStyle(ButtonStyle.Primary)
                    .setCustomId("7DiasCart")
            );
        }

        row.addComponents(
            new ButtonBuilder()
                .setCustomId("cancelOrder")
                .setEmoji("❌")
                .setLabel("Cancelar Pedido")
                .setStyle(ButtonStyle.Danger)
        );

        return row;
    };

    /**
     * Define um timer para inatividade
     * @param {Function} callback 
     * @param {Number} delay 
     */
    setInactivityTimer = (callback, delay) => {
        if (this.inactivityTimer) clearTimeout(this.inactivityTimer);
        this.inactivityTimer = setTimeout(callback, delay);
    };

    /**
     * Lida com o cancelamento por inatividade
     */
    handleInactivity = async () => {
        try {
            await this.user.send({
                embeds: [this.createInactivityEmbed()],
                components: [
                    new ActionRowBuilder().addComponents(
                        new ButtonBuilder()
                            .setCustomId("automaticMessage123")
                            .setLabel("Mensagem Automatica")
                            .setStyle(ButtonStyle.Secondary)
                            .setDisabled(true)
                    )
                ]
            });

            const logEmbed = new EmbedBuilder()
                .setTitle("Sistema de Logs")
                .setAuthor({ name: this.client.user.username, iconURL: this.client.user.displayAvatarURL({ dynamic: true }) })
                .setFooter({ text: this.interaction.guild.name, iconURL: this.interaction.guild.iconURL({ dynamic: true }) })
                .addFields(
                    { name: '👥 | Usuário:', value: `${this.user.username} - \`${this.user.id}\`` },
                    { name: '📝 | Carrinho Fechado:', value: `Produto: ${this.productData.productName} - \`${this.cartId}\`` },
                    { name: '🕒 | Data / Horário do Fechamento:', value: ` ()` },
                    { name: '❔ | Motivo:', value: `Inatividade` }
                );

            await this.sendLog(logEmbed);
            if (this.channel) {
                await this.channel.delete();
                await Cart.deleteOne({ channelId: this.channel.id });
            }
        } catch (error) {
            console.error("Erro ao lidar com inatividade:", error);
        }
    };

    /**
     * Lida com a criação e processamento do pagamento
     * @param {Object} paymentResponse Retorno da criação do pagamento
     */
    processPayment = async (paymentResponse) => {
        try {
            if (!paymentResponse) {
                throw new Error("Resposta de pagamento inválida.");
            }

            const { id, attachment, pixCopyPasteCode } = paymentResponse;

            console.log(`[Payment] - Pagamento criado com sucesso (${id})`);

            const totalAmount = Number(this.productData.preco[this.selectedPlan].preco * this.quantity).toFixed(2);
            await this.message.edit({
                embeds: [
                    new EmbedBuilder()
                        .setDescription("### Resumo do Carrinho"
                            + `\n\`📨\` **ID**: ${this.cartId}`
                            + `\n\`📦\` **Produto**: ${this.productData.productName}`
                            + `\n\`✨\` **Plano**: ${this.capitalize(this.selectedPlan)} (x${this.quantity}) - ${this.days * this.quantity} dias`
                            + `\n\`💸\` **Total**: R$${totalAmount}`
                        ),

                    new EmbedBuilder()
                        .setDescription("- **Pague o Pix via QR CODE ou código pix abaixo**\n- O pagamento será verificado automaticamente\n- Expira em <t::R>")
                        .setImage(`attachment://qrcode.png`)
                ],
                components: [
                    new ActionRowBuilder().addComponents(
                        new ButtonBuilder()
                            .setCustomId("pixCopyPaste")
                            .setLabel("Código copia e cola")
                            .setEmoji("💰")
                            .setStyle(ButtonStyle.Secondary),
                        new ButtonBuilder()
                            .setCustomId("cancelPayment")
                            .setLabel("Cancelar Pedido")
                            .setStyle(ButtonStyle.Danger)
                    )
                ]
            });

            // Enviar o QR Code como anexo
            if (attachment) {
                await this.channel.send({ files: [attachment] });
            }

            // Monitora o status do pagamento em intervalos regulares
            const checkPaymentStatus = setInterval(async () => {
                try {
                    //const status = await this.paymentProcessor.checkPaymentStatus(id);
                    const status = 'approved'

                    console.log(`[Payment] - Status do pagamento (${id}): ${status}`);

                    if (status === "approved") {
                        clearInterval(checkPaymentStatus);
                        await this.handleApprovedPayment(id);
                    } else if (status === "cancelled") {
                        clearInterval(checkPaymentStatus);
                        await this.handleInactivity();
                    }
                    // Outros status podem ser tratados conforme a necessidade
                } catch (error) {
                    console.error("Erro ao verificar status do pagamento:", error);
                }
            }, 60000); // Verifica a cada 60 segundos

        } catch (error) {
            console.error("Erro ao processar pagamento:", error);
        }
    };

    /**
     * Lida com o pagamento aprovado
     * @param {String} paymentId 
     */
    handleApprovedPayment = async (paymentId) => {
        try {
            const cart = await Cart.findOne({ channelId: this.channel.id });
            if (cart && cart.status === "Aguardando...") {
                cart.status = "Processando";
                await cart.save();

                const cargoClientId = '995154994183548953'; // Substitua pelo ID do cargo desejado
                if (cargoClientId) {
                    const member = this.interaction.guild.members.cache.get(this.user.id);
                    if (member) {
                        await member.roles.add(cargoClientId).catch(() => console.log("Usuário já tem cargo."));
                    }
                }

                await this.channel.bulkDelete(50);
                await this.channel.send({
                    content: `✅ Pagamento Aprovado \n🆔 ID da Compra: ${this.cartId}`
                });

                await this.channel.send({
                    content: `${this.user}`,
                    embeds: [
                        new EmbedBuilder()
                            .setTitle("Pagamento Aprovado")
                            .setAuthor({ name: this.client.user.username, iconURL: this.client.user.displayAvatarURL({ dynamic: true }) })
                            .setFooter({ text: this.interaction.guild.name, iconURL: this.interaction.guild.iconURL({ dynamic: true }) })
                            .setDescription(`**O pagamento foi aprovado! Para enviar o seu bot, preciso de algumas informações:**\n\n- **Nome que você irá querer na aplicação**\n- **ID que será setado como dono do bot**\n- **Token do Bot**\n\n**⚠ | Mantenha o token do bot seguro. Não compartilhe com ninguém!**`)
                    ],
                    components: [
                        new ActionRowBuilder().addComponents(
                            new ButtonBuilder()
                                .setLabel("Enviar Bot")
                                .setEmoji("🎉")
                                .setStyle(ButtonStyle.Primary)
                                .setCustomId(`${this.selectedPlan}_${this.days * this.quantity}}_${this.productId}_redeemBot`),
                            new ButtonBuilder()
                                .setLabel("Portal Desenvolvedor")
                                .setEmoji("🤖")
                                .setStyle(ButtonStyle.Link)
                                .setURL("https://discord.com/developers/applications/"),
                            new ButtonBuilder()
                                .setLabel("Tutorial")
                                .setEmoji("🔗")
                                .setStyle(ButtonStyle.Link)
                                .setURL("https://docs.nyox.tech/tutorials/createapp")
                        )
                    ]
                });
            }
        } catch (error) {
            console.error("Erro ao lidar com pagamento aprovado:", error);
        }
    };

    cratePlanItens = () => {
        const { preco } = this.productData;
        const total = Number(preco[this.selectedPlan].preco * this.quantity).toFixed(2);

        const embed = new EmbedBuilder()
            .setDescription(`### Olá, ${this.user}! Seja bem-vindo(a) ao seu carrinho\n-# Você está prestes a adquirir o ${this.productData.productName}, um sistema exclusivo da **Nyox Applications** com a melhor qualidade do mercado.`
                + `\n`
                + `\n\`📦\` **Produto**: ${this.productData.productName}`
                + `\n\`✨\` **Plano**: ${this.capitalize(this.selectedPlan)} (x${this.quantity}) - ${this.days * this.quantity} dias`
                + `\n\`💰\` **Valor**: R$${total}`
            )
            .setColor("#060A18")

        const buttonsRow = new ActionRowBuilder().addComponents(
            new ButtonBuilder()
                .setCustomId("addToCart")
                .setLabel("➕")
                .setStyle(ButtonStyle.Primary),
            new ButtonBuilder()
                .setCustomId("removeFromCart")
                .setLabel("➖")
                .setStyle(ButtonStyle.Secondary),
            new ButtonBuilder()
                .setCustomId("finalizePurchase")
                .setLabel("Confirmar Pedido")
                .setStyle(ButtonStyle.Success)
                .setEmoji("✅"),
            new ButtonBuilder()
                .setCustomId("cancelOrder")
                .setLabel("Cancelar Pedido")
                .setStyle(ButtonStyle.Danger)
                .setEmoji("❌")
        );

        return { embeds: [embed], components: [buttonsRow] }
    };

    /**
     * Lida com a seleção de plano
     * @param {Discord.Interaction} interaction 
     */
    handlePlanSelection = async (interaction, forcePlan) => {
        try {
            // Determina o plano selecionado com base no customId do botão
            switch (forcePlan || interaction.customId) {
                case "7DiasCart":
                    this.selectedPlan = "semanal";
                    this.days = 7;
                    break;
                case "15DiasCart":
                    this.selectedPlan = "quizena";
                    this.days = 15;
                    break;
                case "30DiasCart":
                    this.selectedPlan = "mensal";
                    this.days = 30;
                    break;
                default:
                    return;
            }

            // Atualiza o carrinho no banco de dados com os nomes de campos corretos
            await Cart.findOneAndUpdate(
                { channelId: this.channel.id },
                { quantity: this.quantity, status: "Aguardando...", selectedPlan: this.selectedPlan },
                { new: true }
            );

            await this.message.edit(this.cratePlanItens());

            // Cria a embed de log para registrar a criação do carrinho
            const logEmbed = new EmbedBuilder()
                .setTitle("📝 **Sistema de Logs**")
                .setColor("#FF4500") // Vermelho Alaranjado para logs
                .setAuthor({
                    name: this.client.user.username,
                    iconURL: this.client.user.displayAvatarURL({ dynamic: true })
                })
                .setFooter({
                    text: this.interaction.guild.name,
                    iconURL: this.interaction.guild.iconURL({ dynamic: true })
                })
                .addFields(
                    { name: "👥 **Usuário**", value: `${this.user.username} - \`${this.user.id}\``, inline: false },
                    { name: "🛒 **Criou um Carrinho**", value: `Produto: **${this.productData.productName}** - \`${this.cartId}\``, inline: false },
                    { name: "🕒 **Data / Horário da Compra**", value: `<t:${Math.floor(Date.now() / 1000)}:f> (<t:${Math.floor(Date.now() / 1000)}:R>)`, inline: false }
                );

            // Envia o log para o canal de logs
            await this.sendLog(logEmbed);

            // Reinicia o timer de inatividade (60 segundos - ajuste conforme necessário)
            this.setInactivityTimer(() => {
                this.handleInactivity();
            }, this.inactivityDelay);
        } catch (error) {
            console.error("Erro ao lidar com seleção de plano:", error);
        }
    };

    /**
     * Finaliza a compra e gera os dados de pagamento
     * @param {Discord.Interaction} interaction 
     */
    finalizePurchase = async (interaction) => {
        try {
            clearTimeout(this.inactivityTimer);

            const totalAmount = Number(this.productData.preco[this.selectedPlan].preco * this.quantity).toFixed(2);

            const paymentOptions = {
                amount: Number(totalAmount),
                description: `Saldo - ${this.user.username}`,
                first_name: this.user.firstName || 'Cliente', // Ajuste conforme necessário
                email: this.user.email || 'paymentsinbox@nyox.tech', // Ajuste conforme necessário
                otherData: {
                    notification_url: "https://nyox.tech/api/notifications" // Substitua pela sua URL de notificação
                }
            };

            // Cria o pagamento utilizando PaymentProcessor
            const paymentResponse = await this.paymentProcessor.getPayment(92690421680)
            /*const paymentResponse = await this.paymentProcessor.processPayment(
                paymentOptions.amount,
                paymentOptions.description,
                paymentOptions.first_name,
                paymentOptions.email,
                paymentOptions.otherData
            );*/

            await interaction.deferUpdate()

            if (!paymentResponse) {
                throw new Error("Falha ao criar o pagamento.");
            }

            this.paymentId = paymentResponse.id;
            const payment = new Payment({
                payment_id: paymentResponse.id,
                transaction_amount: paymentOptions.amount,
                description: paymentOptions.description,
                customerId: this.user.id,
                email: paymentOptions.email
            });
            await payment.save()
            await Cart.findOneAndUpdate(
                { channelId: this.channel.id },
                {
                    paymentId: this.paymentId
                },
                { new: true }
            );

            // Processa o pagamento utilizando PaymentProcessor
            await this.processPayment(paymentResponse);
        } catch (error) {
            console.error("Erro ao finalizar pedido:", error);
            await interaction.reply({ content: "Ocorreu um erro ao processar seu pedido. Por favor, tente novamente mais tarde.", ephemeral: true });
        }
    };

    /**
     * Atualiza a quantidade no carrinho (adicionar ou remover)
     * @param {Discord.Interaction} interaction 
     * @param {String} action 
     */
    updateCartQuantity = async (interaction, action) => {
        try {
            if (action === "add") {
                this.quantity += 1;
            } else if (action === "remove") {
                this.quantity -= 1;

                if (this.quantity <= 0) {
                    this.quantity = 1;
                    await interaction.reply({
                        embeds: [
                            new EmbedBuilder()
                                .setDescription("❌ | Você não pode diminuir mais.")
                        ],
                        ephemeral: true
                    });
                    return;
                }
            }

            await Cart.findOneAndUpdate(
                { channelId: this.channel.id },
                { quantity: this.quantity },
                { new: true }
            );

            await interaction.update(this.cratePlanItens());

            // Reinicia o timer de inatividade
            this.setInactivityTimer(() => {
                this.handleInactivity();
            }, this.inactivityDelay);
        } catch (error) {
            console.error("Erro ao atualizar quantidade do carrinho:", error);
        }
    };

    /**
     * Lida com o cancelamento da ordem
     * @param {Discord.Interaction} interaction 
     */
    handleCancellation = async (interaction) => {
        try {
            const logEmbed = new EmbedBuilder()
                .setTitle("Sistema de Logs")
                .setAuthor({ name: this.client.user.username, iconURL: this.client.user.displayAvatarURL({ dynamic: true }) })
                .setFooter({ text: this.interaction.guild.name, iconURL: this.interaction.guild.iconURL({ dynamic: true }) })
                .addFields(
                    { name: '👥 | Usuário:', value: `${this.user.username} - \`${this.user.id}\`` },
                    { name: '📝 | Encerrou um Carrinho:', value: `Produto: ${this.productData.productName} - \`${this.cartId}\`` },
                    { name: '🕒 | Data / Horário do Fechamento:', value: `<t:${Math.floor(Date.now() / 1000)}:f> (<t:${Math.floor(Date.now() / 1000)}:R>)` },
                    { name: '❔ | Motivo:', value: `Cancelado pelo usuário.` }
                );

            await this.sendLog(logEmbed);
            if (this.channel) {
                await Cart.deleteOne({ channelId: this.channel.id });
                await this.channel.delete();
            }
        } catch (error) {
            console.error("Erro ao lidar com cancelamento:", error);
        }
    };

    /**
     * Lida com o cancelamento da ordem via botão de pagamento
